import math

FLOOR = (0.0, 1.0, 0.0)
RAMP = (-0.6, 0.8, 0.5)

def signed_distance(px, py, nx, ny, offset):
    d = nx * px + ny * py - offset
    return d

print("normal lengths", round(math.hypot(FLOOR[0], FLOOR[1]), 6), round(math.hypot(RAMP[0], RAMP[1]), 6))
for px, py in ((0.0, 0.5), (0.0, -0.2), (1.2, 0.9)):
    for name, plane in (("floor", FLOOR), ("ramp", RAMP)):
        print(name, px, py, round(signed_distance(px, py, plane[0], plane[1], plane[2]), 6))

def overlap_1d(a_min, a_max, b_min, b_max):
    amount = min(a_max, b_max) - max(a_min, b_min)
    return amount

def box_overlap(a, b):
    ox = overlap_1d(a[0], a[2], b[0], b[2])
    oy = overlap_1d(a[1], a[3], b[1], b[3])
    if ox <= 0.0 or oy <= 0.0:
        return None
    if ox < oy:
        return ox, "x"
    return oy, "y"

