    ("shallow on x", (0.0, 0.0, 1.0, 1.0), (0.9, 0.2, 2.0, 1.4)),
    ("shallow on y", (0.0, 0.0, 1.0, 1.0), (0.2, 0.85, 1.4, 2.0)),
    ("clear", (0.0, 0.0, 1.0, 1.0), (1.5, 1.5, 2.0, 2.0)),
)
for name, a, b in pairs:
    result = box_overlap(a, b)
    shortest = "none" if result is None else result[1] + " " + str(round(result[0], 6))
    print(name, round(overlap_1d(a[0], a[2], b[0], b[2]), 6), round(overlap_1d(a[1], a[3], b[1], b[3]), 6), shortest)

