WALL_MIN = 2.03
WALL_MAX = 2.08
SPEED = 500.0
DURATION = 0.02

def discrete_hits(dt):
    x = 0.0
    hits = 0
    for _ in range(int(round(DURATION / dt))):
        x = x + SPEED * dt
        if WALL_MIN <= x <= WALL_MAX:
            hits = hits + 1
    return hits

def swept_hits(dt):
    x = 0.0
    hits = 0
    for _ in range(int(round(DURATION / dt))):
        x_next = x + SPEED * dt
        if x_next == x:
            continue
        toi = (WALL_MIN - x) / (x_next - x)
        if 0.0 <= toi <= 1.0:
            hits = hits + 1
        x = x_next
    return hits

for dt in (0.004, 0.0004, 0.00004):
    print(dt, "discrete", discrete_hits(dt), "swept", swept_hits(dt))

