def solve_contacts(ys, vs):
    for i in range(len(ys) - 1, 0, -1):
        gap = ys[i] - ys[i - 1]
        depth = 2.0 * RADIUS - gap
        if depth > 0.0:
            ys[i] = ys[i] + depth * 0.5
            ys[i - 1] = ys[i - 1] - depth * 0.5
            vs[i] = 0.0
            vs[i - 1] = 0.0
