DT = 0.002
STEPS = 3000
SNAPSHOT_EVERY = 250

def advance(state, steps):
    x, v = state
    for _ in range(steps):
        v = v + (0.6 - v) * 0.01
        x = x + v * DT
    return (x, v)

snapshots = {}
state = (0.0, 0.0)
for i in range(0, STEPS, SNAPSHOT_EVERY):
    snapshots[i] = state
    state = advance(state, SNAPSHOT_EVERY)

def seek(target):
    key = (target // SNAPSHOT_EVERY) * SNAPSHOT_EVERY
    resimulated = target - key
    return advance(snapshots[key], resimulated), resimulated

for target in (733, 250, 2999):
    reached, resimulated = seek(target)
    full = advance((0.0, 0.0), target)
    print("target", target, "steps re simulated", resimulated, "of", target,
